INVENTORY_JS = r'''
const fs = require('node:fs');
const ts = require(process.argv[1]);
const input = JSON.parse(fs.readFileSync(0, 'utf8'));
function canonical(text) {
  const scan = ts.createScanner(ts.ScriptTarget.Latest, true, ts.LanguageVariant.Standard, text);
  const tokens = [];
  for (let kind = scan.scan(); kind !== ts.SyntaxKind.EndOfFileToken; kind = scan.scan())
    tokens.push([kind, scan.getTokenText()]);
  return JSON.stringify(tokens);
}
const result = {};
for (const [path, text] of Object.entries(input)) {
  const file = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  if (file.parseDiagnostics.length) throw Error('Review cannot inventory malformed TypeScript: ' + path);
  const records = {cases: [], assertions: [], forbidden: [], sql_queries: [], unchecked_cases: [],
    inactive_ui_givens: [], ui_given_returns: []};
  const observationImports = new Set();
  for (const statement of file.statements) {
    const bindings = ts.isImportDeclaration(statement) && statement.importClause?.namedBindings;
    const fixtureModule = ts.isImportDeclaration(statement)
      && /(?:^|\/)(?:context|http|database)\.[jt]s$/.test(statement.moduleSpecifier.text || '');
    if (fixtureModule && bindings && ts.isNamedImports(bindings)) for (const item of bindings.elements)
      if (['queryOne', 'queryRows'].includes((item.propertyName || item.name).text))
        observationImports.add(item.name.text);
  }
  function root(expr) {
    while (ts.isPropertyAccessExpression(expr) || ts.isCallExpression(expr)) expr = expr.expression;
    return ts.isIdentifier(expr) ? expr.text : '';
  }
  const browserActions = new Set(["goto", "reload", "goBack", "goForward", "click", "dblclick",
    "fill", "clear", "press", "check", "uncheck", "selectOption", "hover", "focus", "blur",
    "getByRole", "getByText", "getByLabel", "getByTestId", "getByPlaceholder", "getByAltText",
    "getByTitle", "locator", "filter", "nth", "first", "last", "inputValue", "textContent",
    "innerText", "getAttribute", "isVisible", "isHidden", "isEnabled", "isDisabled", "count"]);
  function hasPossibleCheck(node) {
    if (ts.isIfStatement(node) && node.expression.kind === ts.SyntaxKind.FalseKeyword)
      return node.elseStatement ? hasPossibleCheck(node.elseStatement) : false;
    if (ts.isIfStatement(node) && node.expression.kind === ts.SyntaxKind.TrueKeyword)
      return hasPossibleCheck(node.thenStatement);
    if (ts.isThrowStatement(node)) return true;
    if (ts.isCallExpression(node)) {
      const expr = node.expression;
      if (ts.isPropertyAccessExpression(expr) && ts.isCallExpression(expr.expression)
          && expr.expression.expression.getText(file) === "expect") {
        const value = expr.expression.arguments[0];
        const expected = node.arguments[0];
        if (value && ((expr.name.text === "toBeTruthy" && value.kind === ts.SyntaxKind.TrueKeyword)
          || (expr.name.text === "toBeFalsy" && value.kind === ts.SyntaxKind.FalseKeyword)
          || (expected && ["toBe", "toEqual", "toStrictEqual"].includes(expr.name.text)
            && (ts.isLiteralExpression(value) || [ts.SyntaxKind.TrueKeyword, ts.SyntaxKind.FalseKeyword,
              ts.SyntaxKind.NullKeyword].includes(value.kind))
            && canonical(value.getText(file)) === canonical(expected.getText(file))))) return false;
      }
      // A bare expect(value) only constructs an assertion object.
      const expectFactory = ts.isIdentifier(expr) && expr.text === "expect"
        || ts.isPropertyAccessExpression(expr) && expr.expression.getText(file) === "expect"
          && ["soft", "poll"].includes(expr.name.text);
      const browserAction = ts.isPropertyAccessExpression(expr) && root(expr) === "page"
        && browserActions.has(expr.name.text);
      const wrapper = ts.isIdentifier(expr) && ["uiScenario", "acceptancePhase"].includes(expr.text)
        || ts.isParenthesizedExpression(expr)
          && (ts.isArrowFunction(expr.expression) || ts.isFunctionExpression(expr.expression));
      if (!expectFactory && !browserAction && !wrapper) return true;
    }
    return ts.forEachChild(node, hasPossibleCheck) ?? false;
  }
  function phaseCallback(node) {
    if (!ts.isArrowFunction(node)) return node;
    const body = node.body;
    if (ts.isCallExpression(body) && body.expression.getText(file) === "acceptancePhase"
        && body.arguments[2] && ts.isFunctionLike(body.arguments[2])) return body.arguments[2];
    return node;
  }
  function uncheckedOutcomes(callback) {
    const steps = [];
    function inspect(node) {
      if (ts.isFunctionExpression(node) && node.name?.text === "arcAcceptanceThen"
          && !hasPossibleCheck(node.body)) steps.push("Then at line " + (file.getLineAndCharacterOfPosition(node.getStart(file)).line + 1));
      if (ts.isCallExpression(node) && node.expression.getText(file) === "uiScenario"
          && node.arguments[1] && ts.isObjectLiteralExpression(node.arguments[1])) {
        const then = node.arguments[1].properties.find(property =>
          ts.isPropertyAssignment(property) && property.name.getText(file) === "then");
        const action = then && phaseCallback(then.initializer);
        if (action && ts.isFunctionLike(action) && !hasPossibleCheck(action.body))
          steps.push("Then for " + node.arguments[0].getText(file));
      }
      ts.forEachChild(node, inspect);
    }
    inspect(callback.body);
    return steps;
  }
  function walk(node, scope = '$shared', guards = [], caseTitle = '') {
    if (ts.isCallExpression(node) && node.expression.getText(file) === "uiScenario"
        && node.arguments[0] && ts.isStringLiteral(node.arguments[0])
        && node.arguments[1] && ts.isObjectLiteralExpression(node.arguments[1])) {
      const given = node.arguments[1].properties.find(property =>
        ts.isPropertyAssignment(property) && property.name.getText(file) === "given");
      function hasAction(statement) {
        if (ts.isFunctionLike(statement)) return false;
        if (ts.isCallExpression(statement)) return true;
        return ts.forEachChild(statement, hasAction) ?? false;
      }
      const callback = given && phaseCallback(given.initializer);
      if (callback && ts.isFunctionLike(callback)) {
        const step = node.arguments[0].text;
        if (!hasAction(callback.body)) records.inactive_ui_givens.push(step);
        function inspectReturn(statement) {
          if (ts.isFunctionLike(statement)) return;
          if (ts.isReturnStatement(statement)) inspectArray(statement.expression);
          ts.forEachChild(statement, inspectReturn);
        }
        function inspectArray(expression) {
          while (expression && (ts.isParenthesizedExpression(expression) || ts.isAsExpression(expression)
              || ts.isSatisfiesExpression(expression))) expression = expression.expression;
          if (!expression || !ts.isArrayLiteralExpression(expression)) return;
          const entities = [];
          for (const element of expression.elements) {
            if (!ts.isObjectLiteralExpression(element) || element.properties.some(ts.isSpreadAssignment)) return;
            const property = element.properties.find(value => ts.isPropertyAssignment(value)
                && value.name && (ts.isIdentifier(value.name) || ts.isStringLiteral(value.name))
                && value.name.text === "entity");
            if (!property || !ts.isStringLiteralLike(property.initializer)) return;
            entities.push(property.initializer.text);
          }
          records.ui_given_returns.push({step_id: step, case: caseTitle, entities});
        }
        if (ts.isBlock(callback.body)) inspectReturn(callback.body);
        else inspectArray(callback.body);
      }
    }
    // Inspect only literal queries on the compiler-provided database fixture.
    // Dynamic SQL and unrelated prose are not inferred or executed here.
    if (ts.isCallExpression(node) && (
        (ts.isPropertyAccessExpression(node.expression)
          && node.expression.expression.getText(file) === 'database'
          && node.expression.name.text === 'prepare') ||
        (ts.isIdentifier(node.expression) && observationImports.has(node.expression.text)
          && node.arguments.length >= 2))) {
      const query = node.arguments[ts.isIdentifier(node.expression) ? 1 : 0];
      if (query && (ts.isStringLiteral(query) || ts.isNoSubstitutionTemplateLiteral(query)))
        records.sql_queries.push({sql: query.text,
          line: file.getLineAndCharacterOfPosition(query.getStart(file)).line + 1});
    }
    if (ts.isCallExpression(node) && ['test', 'apiTest'].includes(root(node.expression))) {
      const expr = node.expression.getText(file);
      if (/\.(skip|fixme|only|fail)\b/.test(expr)) records.forbidden.push(expr);
      const callback = node.arguments.find(n => ts.isArrowFunction(n) || ts.isFunctionExpression(n));
      if (callback && node.arguments.length >= 2) {
        const title = canonical(node.arguments[0].getText(file));
        const key = scope + '/' + title;
        if (!/\.describe\b/.test(expr)) {
          records.cases.push(key);
          const title = node.arguments[0].getText(file);
          if (!hasPossibleCheck(callback.body)) records.unchecked_cases.push(title);
          else for (const step of uncheckedOutcomes(callback)) records.unchecked_cases.push(title + " (" + step + ")");
        }
        const testTitle = ts.isStringLiteralLike(node.arguments[0]) ? node.arguments[0].text : caseTitle;
        for (const child of node.arguments) walk(child, key, [], testTitle);
        return;
      }
    }
    if (ts.isCallExpression(node) && (root(node.expression) === 'assert'
        || (ts.isPropertyAccessExpression(node.expression) && root(node.expression) === 'expect'
        && node.expression.name.text !== 'poll' && node.expression.name.text !== 'soft'))) {
      const expression = node.getText(file);
      records.assertions.push({scope, expression, canonical: canonical(expression), guards});
    }
    let next = guards;
    if (ts.isIfStatement(node) || ts.isConditionalExpression(node) || ts.isWhileStatement(node)
        || ts.isForStatement(node) || ts.isForOfStatement(node) || ts.isForInStatement(node)
        || ts.isTryStatement(node) || ts.isCatchClause(node)) {
      const head = ts.isTryStatement(node) ? 'try' : ts.isCatchClause(node) ? 'catch'
        : (node.expression || node.condition || node.initializer || node).getText(file);
      next = [...guards, canonical(head)];
    }
    ts.forEachChild(node, child => walk(child, scope, next, caseTitle));
  }
  walk(file);
  result[path] = records;
}
process.stdout.write(JSON.stringify(result));
'''


def inventory(output, sources):
    modules = Path(output) / 'node_modules'
    if not (modules / 'typescript').is_dir():
        modules = Path(os.environ.get('ARC_DB_TEST_NODE_MODULES', str(modules)))
    node = shutil.which('node')
    if not node or not (modules / 'typescript').is_dir():
        raise ValueError('TypeScript runtime is required to preserve test review witnesses')
    result = subprocess.run([node, '-e', INVENTORY_JS, str(modules / 'typescript')],
        input=json.dumps(sources), capture_output=True, text=True, encoding='utf8', timeout=30)
    if result.returncode:
        raise ValueError('Cannot inventory test review: ' + result.stderr[-3000:])
    records = json.loads(result.stdout)
    for record in records.values():
        for assertion in record['assertions']:
            assertion['id'] = sha256(json.dumps([assertion['scope'], assertion['canonical'],
                assertion['guards']], separators=(',', ':')).encode()).hexdigest()[:20]
    return records


REVIEW_RULES = '''Review edits require diagnosis.cause=test_requirement_mismatch or
test_overconstraint, a reason, and diagnosis.source_quote copied exactly from evidence
supplied for the edited owner. Original requirements control business expectations.
Supplied API/schema/runtime contracts may justify setup or interface-use corrections
while preserving assertions; generated handlers and actual output are not authority.
If a derived contract conflicts with an original requirement, retain the requirement
and report the conflict; do not change expectations to the derived contract.
implementation/environment means
tool_calls=[]: application repair owns those failures. Existing case identities and
assertions in task.review_baseline are protected. Do not delete/rename cases or add
skip/fixme/only/fail. A necessary assertion correction requires assertion_corrections:
[{path, old_id, replacement, source_quote, reason}]. replacement is the exact new
assertion expression, old_id is its review_baseline assertion id, and source_quote
is an exact excerpt of that owner's original requirement. Other assertions must
remain in their original case/control scope. Preserve every business obligation;
an evidence quote authorizes review, not weakening expectations to current output.
review_baseline is the immutable original inventory; files/read_files contain current
source. A review validation rejection is not a new test execution. Retained failing
test output is the last observed execution, not proof the edited source was rerun.
replacement must be the exact assertion expression without its trailing semicolon.'''


class TestReviewWitnesses:
    def __init__(self, output, sources, requirements, *, contracts=None):
        self.output, self.sources = output, sources
        self.requirements = {p: json.dumps(r, ensure_ascii=False) for p, r in requirements.items()}
        self.contracts = {p: json.dumps(r, ensure_ascii=False) for p, r in (contracts or {}).items()}
        self.before = inventory(output, sources)
        if any(not r['cases'] or r['forbidden'] for r in self.before.values()):
            raise ValueError('Review baseline must contain active, identifiable test cases')
        self.response = {}
        self.evidence = {}
        self.corrections = {}

    def quoted(self, path, quote, *, contracts=False):
        # Also accept raw newlines/quotes from original text, not JSON escaping.
        encoded = (self.contracts if contracts else self.requirements).get(path)
        if encoded is None:return False
        original = json.loads(encoded)
        def strings(value):
            if isinstance(value, str):yield value
            elif isinstance(value, dict):
                for v in value.values():yield from strings(v)
            elif isinstance(value, list):
                for v in value:yield from strings(v)
        return isinstance(quote, str) and len(quote.strip()) >= 8 and any(quote in s for s in strings(original))
